100				return "NOT_HEAVY_FAILURE", "Эвакуатор нужен для тяжёлой поломки"
101			}
102		case "dispatch_service":
103			if t.State != "failed" || t.Failure != "light" {
104				return "NOT_LIGHT_FAILURE", "Выездной ремонт доступен при лёгкой поломке"
105			}
106		case "preventive_service":
107			if t.Failure != "" || t.Maintenance || fuelState(t) || recoveryState(t) {
108				return "TRUCK_UNAVAILABLE", "Машина уже на обслуживании или неисправна"
109			}
110		}
111		var chosen *ServiceVehicle
112		var path []string
113		end := 1.0
114		best := math.Inf(1)
115		for _, v := range s.Vehicles {
116			if v.Kind != kind || v.State != "idle" || (cmd.Parameters.VehicleID != "" && v.ID != cmd.Parameters.VehicleID) {
117				continue
118			}
119			if kind == "service" {
120				r := s.repairAt(v.Home)
121				if r == nil || r.Current != "" || len(r.Queue) > 0 {
122					continue
123				}
124			}
125			p, e, d := approach(c, v.Node, t)
126			if len(p) > 0 && d < best {
